# connected-component largest size for color 8, within each 3x3 tile
import numpy as np
arr=np.array(grid)
def largest8(a, color=8):
    pts={(i,j) for i in range(a.shape[0]) for j in range(a.shape[1]) if a[i,j]==color}
    best=0
    while pts:
        stack=[pts.pop()]; n=0
        while stack:
            i,j=stack.pop(); n+=1
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    q=(i+di,j+dj)
                    if (di or dj) and q in pts:
                        pts.remove(q); stack.append(q)
        best=max(best,n)
    return best
